package otp

import (
	"context"
	"crypto/rand"
	"io"
	"time"
)

// CodeConsumer borrows the freshly generated bytes only for this synchronous
// invocation. Do not retain, log or format them or start asynchronous work with
// them. Copy only into the configured secret-envelope protected delivery intent
// and compute the scope-bound keyed digest before returning. Implementations
// must honor context cancellation; Generate does not spawn goroutines or forcibly
// terminate callbacks. Callback errors are normalized to ErrCodeUse, not retained.
type CodeConsumer func(context.Context, []byte) error

// Generate draws an unbiased code from the profile with crypto/rand and lends
// it to use. It derives a context capped at five seconds and rejects nil/zero
// inputs before generation. Random sampling is capped at 32 draws per output
// symbol, with cancellation between draws; OS randomness reads themselves are
// not forcibly interruptible. No weak source or modulo-only fallback is used.
// The borrowed slice is cleared on return, error and callback panic. A panic
// propagates; context cancellation overrides a callback error. Copies retained
// by a violating callback cannot be cleared by this package. Generation neither
// persists nor issues a challenge; use the durable workflow before delivery.
func (p CodeProfile) Generate(ctx context.Context, use CodeConsumer) error {
	return p.generate(ctx, rand.Reader, use)
}

func (p CodeProfile) generate(ctx context.Context, entropy io.Reader, use CodeConsumer) error {
	if _, err := p.Bindings(); err != nil {
		return err
	}
	if ctx == nil || use == nil || entropy == nil {
		return ErrInvalidGeneration
	}
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	code := make([]byte, p.spec.Length)
	defer clear(code)
	var sample [1]byte
	defer clear(sample[:])
	n := len(p.spec.Alphabet)
	threshold := 256 - 256%n
	accepted := 0
	for draw := 0; draw < p.spec.Length*32 && accepted < len(code); draw++ {
		if err := ctx.Err(); err != nil {
			return err
		}
		_, err := io.ReadFull(entropy, sample[:])
		if e := ctx.Err(); e != nil {
			return e
		}
		if err != nil {
			return ErrGenerationUnavailable
		}
		if int(sample[0]) >= threshold {
			continue
		}
		code[accepted] = p.spec.Alphabet[int(sample[0])%n]
		accepted++
	}
	if accepted != len(code) {
		return ErrGenerationUnavailable
	}
	err := use(ctx, code)
	if e := ctx.Err(); e != nil {
		return e
	}
	if err != nil {
		return ErrCodeUse
	}
	return nil
}
